preset_css:
/* CRT Cyberpunk Inject */
.main-header { border-bottom: 2px solid var(--accent); box-shadow: 0 0 10px var(--accent); }
.mor-post, .runelite-panel { border: 1px solid var(--border-color); position: relative; }
.mor-post::before { content: ''; position: absolute; top: 0; left: 0; right: 0; bottom: 0; background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06)); background-size: 100% 2px, 3px 100%; pointer-events: none; z-index: 50; }
h1, h2, h3 { text-shadow: 2px 0px 0px var(--accent), -2px 0px 0px var(--fg-muted); letter-spacing: -1px; }
